        en.x = lx; en.y = ly; const dn = fire(edx, edy, lx, ly);
        const openLive = openSpan();
        const cz0 = MAP.cz[ (ovlAt[1] | 0) * N + (ovlAt[0] | 0) ];
        MAP.cz[ovlAt[1] * N + ovlAt[0]] = CZ_DEF; linkBoundaries();
