    for (let j = 1; j <= 6; j++) MAP.fz[base + j] += 2;
    linkBoundaries();
    const blockedUp = (MAP.vb[base] & VB_BLOCK) ? 1 : 0;
    for (let j = 1; j <= 6; j++) MAP.fz[base + j] -= 2;
    linkBoundaries();
