    run('globalThis.__L = MAP.light.slice(); globalThis.__A = MAP.amb');
    run('MAP.amb = 0; for(let i=0;i<MW*MH;i++)MAP.light[i] = 0');
    const s2 = pair(PARKO + P0, HID);
    run('MAP.light.set(globalThis.__L); MAP.amb = globalThis.__A');
    const m2 = mask(s2);
